      <ResizableHandle aria-label={en ? "Content" : "正文"} />
      <ResizablePanel id="resizable-demo-console" defaultSize={30} minSize={20} collapsible onCollapse={() => setCollapsed(true)} onExpand={() => setCollapsed(false)}>
