  /** 第几级：填满的格数，1 到 max 的整数。没有级别就不放这个标记，所以没有 0。 */
  level: number;
  /** 一共几级：格的总数，2 到 5 的整数。同一列里的标记用同一个 max。 */
  max?: number;
  /** 状态类别：由调用方声明，组件不从级别猜好坏（随类赋彩）。不给时填充用焦墨。 */
  tone?: Tone;
  /** 这一级叫什么，必填。名称由应用声明：库不内置任何级别用词，也不从数字推断。 */
  label: string;
  /**
   * visible：格后面跟着名称。hidden：画面上只剩格，名称仍是这个标记的可访问名称——
   * 名称由同一行的别的文字或表头承担时用。
   */
  name?: "visible" | "hidden";
}

